/// Resolves rules from the model used by the target chat, preserving role/provider identity.
pub(crate) fn summaryCustomRulesForChat(
    &self,
    chatId: Option<&str>,
    roleCardIdOverride: Option<&str>,
    providerIdOverride: Option<&str>,
    modelIdOverride: Option<&str>,
) -> String {
    let result = (|| -> Result<String, String> {
        let binding = match (providerIdOverride, modelIdOverride) {
            (Some(provider), Some(model)) if !provider.trim().is_empty() && !model.trim().is_empty()
                => Some((provider.to_string(), model.to_string())),
            (None, None) => {
                let targetChat = self.chatHistoryDelegate.chatHistoriesFlow.value()
                    .into_iter().find(|chat| Some(chat.id.as_str()) == chatId);
                let roleId = match roleCardIdOverride {
                    Some(id) => Some(id.to_string()),
                    None if targetChat.as_ref().is_some_and(|chat| chat.characterGroupId.is_some()) => None,
                    None => Some(self.resolveRoleCardIdForSend(targetChat.as_ref())
                        .map_err(|error| error.to_string())?),
                };
                match roleId {
                    Some(id) => {
                        let (provider, model) = self.resolveRegenerationChatModelOverrides(&id)?;
                        provider.zip(model)
                    }
                    None => None,
                }
            }
            _ => return Err("Summary chat provider/model override must be set together".to_string()),
        };
        let (provider, model) = match binding {
            Some(binding) => binding,
            None => {
                let binding = self.messageProcessingDelegate.functionalConfigManager
                    .getModelBindingForFunction(FunctionType::CHAT)
                    .map_err(|error| error.to_string())?;
                (binding.providerId, binding.modelId)
            }
        };
        Ok(self.messageProcessingDelegate.modelConfigManager
            .getResolvedModelConfig(&provider, &model)
            .map_err(|error| error.to_string())?.summary.summaryCustomRules)
    })();
    match result {
        Ok(rules) => rules,
        Err(error) => {
            AppLogger::w("MessageCoordinationDelegate",
                &format!("Unable to read target chat summary rules; continuing without custom rules: {error}"));
            String::new()
        }
    }
}

